import{_ as o,C as r,c as n,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Stages","description":"","frontmatter":{},"headers":[],"relativePath":"master/getting-started/stages.md","filePath":"master/getting-started/stages.md","lastUpdated":1793074831000}'),l={name:"master/getting-started/stages.md"};function d(g,e,c,h,m,u){const a=r("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="stages" tabindex="-1">Stages <a class="header-anchor" href="#stages" aria-label="Permalink to &quot;Stages&quot;">​</a></h1><p><strong>Stages</strong> show how far a record has moved through a process. A maintenance request moves from new to repaired. A job application moves from first contact to hired. A task moves from to do to done. Stages are the same idea in every module, so you learn them once.</p><blockquote><p><strong>In simple words:</strong> A stage is a step on the way to finished. You decide the steps, and you move each record from one step to the next.</p></blockquote><h2 id="where-stages-are-used" tabindex="-1">Where stages are used <a class="header-anchor" href="#where-stages-are-used" aria-label="Permalink to &quot;Where stages are used&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Stages for</th><th>Menu path</th></tr></thead><tbody><tr><td>Maintenance</td><td>Maintenance requests</td><td><code>Maintenance → Configurations → Stages</code></td></tr><tr><td>Recruitment</td><td>Job applications</td><td><code>Recruitment → Configuration → Stages</code></td></tr><tr><td>Project</td><td>Projects</td><td><code>Project → Configurations → Project Stages</code></td></tr><tr><td>Project</td><td>Tasks</td><td><code>Project → Configurations → Task Stages</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Project stages are off by default. Turn them on before you use them. See <a href="#turn-on-project-stages">Turn on project stages</a>.</p></div><h2 id="change-stages" tabindex="-1">Change stages <a class="header-anchor" href="#change-stages" aria-label="Permalink to &quot;Change stages&quot;">​</a></h2><p>Every stage page works the same way:</p><ol><li>Open the menu path from the table above.</li><li>Click <strong>New</strong> to add a stage, or click <strong>Edit</strong> on a row to change one.</li><li>Fill in the fields and save.</li></ol><p>The list shows the stages in the order they appear in the process. To change the order, use the drag handle on a row and drop it in its new place. Click <strong>Delete</strong> to remove a stage.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A stage that is still used by records cannot always be deleted. Move those records to another stage first.</p></div><h2 id="fields-by-module" tabindex="-1">Fields by module <a class="header-anchor" href="#fields-by-module" aria-label="Permalink to &quot;Fields by module&quot;">​</a></h2><h3 id="maintenance-stages" tabindex="-1">Maintenance stages <a class="header-anchor" href="#maintenance-stages" aria-label="Permalink to &quot;Maintenance stages&quot;">​</a></h3><ul><li><strong><em>Name:</em></strong> The name of the stage, for example <code>New Request</code> or <code>In Progress</code>.</li><li><strong><em>Done:</em></strong> Turn on for the last step. A request in a done stage counts as finished.</li></ul>',14)),s(a,{src:"/images1/maintenance/set_stage_form.png",alt:"New Stage window with the Name and Done fields"}),e[1]||(e[1]=t('<p>See <a href="./../supply-chain/maintenance/requests/process-request.html">Maintenance requests</a> for how requests move between stages.</p><h3 id="recruitment-stages" tabindex="-1">Recruitment stages <a class="header-anchor" href="#recruitment-stages" aria-label="Permalink to &quot;Recruitment stages&quot;">​</a></h3><ul><li><strong><em>Stage Name:</em></strong> The name of the stage, for example <code>Interview</code>.</li><li><strong><em>Sequence Order:</em></strong> The position of the stage in the list.</li><li><strong><em>Requirements:</em></strong> Notes on what must be done before a candidate leaves this stage.</li><li><strong><em>Gray Label, Red Label, Green Label:</em></strong> Your own text for the three status marks on an application in this stage.</li><li><strong><em>Job Positions:</em></strong> Limit the stage to chosen jobs. Leave it empty to use the stage for all jobs.</li><li><strong><em>Folded:</em></strong> Collapse this stage on the board.</li><li><strong><em>Hired Stage:</em></strong> Mark the stage that means the candidate is hired.</li><li><strong><em>Default Stage:</em></strong> Use this stage for every new application.</li></ul>',3)),s(a,{src:"/images1/recruitment/stages_general.png",alt:"Recruitment stage form, General Information section"}),e[2]||(e[2]=t('<h3 id="project-and-task-stages" tabindex="-1">Project and task stages <a class="header-anchor" href="#project-and-task-stages" aria-label="Permalink to &quot;Project and task stages&quot;">​</a></h3><ul><li><strong><em>Name:</em></strong> The name of the stage, for example <code>Planning</code> or <code>In Review</code>.</li><li><strong><em>Project:</em></strong> Tasks stages only. The project the stage belongs to. This field is required.</li></ul>',2)),s(a,{src:"/images1/project/task_stage_1.png",alt:"Task stage form with Name and Project"}),e[3]||(e[3]=t('<h4 id="turn-on-project-stages" tabindex="-1">Turn on project stages <a class="header-anchor" href="#turn-on-project-stages" aria-label="Permalink to &quot;Turn on project stages&quot;">​</a></h4><ol><li>Go to <code>Project → Settings → Manage Tasks</code>.</li><li>Turn on <strong>Enable Project Stages</strong>.</li><li>Save the changes.</li></ol><p>The <strong>Project Stages</strong> page then appears under <strong>Configurations</strong>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../services/project/configuration/">Project configurations</a></li><li><a href="./../human-resources/recruitment/setup/stages.html">Recruitment configuration</a></li></ul>',5))])}const _=o(l,[["render",d]]);export{f as __pageData,_ as default};
